CREATE TABLE streaks (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, current_streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0, last_activity_date DATE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE achievements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(60) UNIQUE NOT NULL, title VARCHAR(120) NOT NULL, description TEXT NOT NULL, icon VARCHAR(20) NOT NULL, threshold INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE user_achievements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, achievement_id UUID NOT NULL REFERENCES achievements(id) ON DELETE CASCADE, earned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,achievement_id));
CREATE TABLE weekly_challenges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), week_start DATE NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, skill VARCHAR(20), target_count INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE user_challenges (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, challenge_id UUID NOT NULL REFERENCES weekly_challenges(id) ON DELETE CASCADE, progress INTEGER NOT NULL DEFAULT 0, completed_at TIMESTAMPTZ, PRIMARY KEY(user_id,challenge_id));
CREATE TABLE community_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, topic VARCHAR(80), status VARCHAR(20) NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), post_id UUID NOT NULL REFERENCES community_posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE community_reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id UUID REFERENCES community_posts(id) ON DELETE CASCADE, comment_id UUID REFERENCES comments(id) ON DELETE CASCADE, reason VARCHAR(80) NOT NULL, details TEXT, status VARCHAR(20) NOT NULL DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK(post_id IS NOT NULL OR comment_id IS NOT NULL));
INSERT INTO achievements(code,title,description,icon,threshold) VALUES ('first_step','First step','Complete your first study task.','🌱',1),('seven_day_streak','Seven day streak','Study for seven consecutive days.','🔥',7),('practice_ten','Practice explorer','Complete ten practice activities.','🏅',10) ON CONFLICT(code) DO NOTHING;
INSERT INTO weekly_challenges(week_start,title,description,skill,target_count) VALUES (date_trunc('week',CURRENT_DATE)::date,'Consistency week','Complete three planned learning tasks this week.',NULL,3) ON CONFLICT(week_start) DO NOTHING;
